export function isPersonSubformCompleteForOnboarding(
  v: IdentificatiePersonSubformValue,
  options: {
    /** When titel wordt in het subform afzonderlijk gevraagd (bv. factuurcontact zonder preset-kolom). */
    requireInlineHonorificTitle?: boolean;
